--

INSERT INTO `simulaciones` (`id`, `usuario_id`, `cultivo_id`, `nombre`, `modelo_usado`, `temperatura`, `humedad`, `precipitacion`, `fertilizante`, `ph_suelo`, `tipo_suelo`, `area_simulada`, `rendimiento_estimado`, `produccion_total`, `confianza`, `shap_json`, `recomendaciones_json`, `fecha`, `categoria_cosecha`, `escenarios_json`) VALUES
(19, 13, 16, 'Simulación 07/07/2026 07:17', 'xgboost', 26.30, 82.90, 1320.00, 95.00, 7.10, 'franco', 2.58, 5.6130, 14.48, 64.00, '{\"area\":0,\"fertilizante\":-0.3166,\"humedad\":-0.0308,\"phSuelo\":-0.3537,\"precipitacion\":0.0787,\"temperatura\":0.219,\"tipoSuelo\":-0.0103}', '[\"\\u2705 Temperatura \\u00f3ptima (25.9\\u00b0C) alineada con los requerimientos (21-27\\u00b0C).\",\"\\u26a0\\ufe0f Humedad excesiva (91.0%). Vigilar la aparici\\u00f3n de enfermedades f\\u00fangicas en las mazorcas.\",\"\\u26a0\\ufe0f Precipitaci\\u00f3n (810 mm) supera el requerimiento \\u00f3ptimo (600-800 mm). Asegurar limpieza de drenajes.\",\"\\u26a0\\ufe0f Fertilizaci\\u00f3n baja (95 kg N\\/ha). Dosis recomendada: 180-200 kg N\\/ha. Fraccionamiento sugerido: 3 aplicaciones: \\u2022 Siembra \\u2022 30 dds \\u2022 55\\u201360 dds.\",\"\\u26a0\\ufe0f pH del suelo alcalino (7.1). Rango \\u00f3ptimo: 6.0-6.5. Considerar materia org\\u00e1nica para bajar el pH.\"]', '2026-07-07 00:17:14', 'Baja', '{\"lluvioso\":{\"produccion\":12.75,\"rendimiento\":4.94},\"sequia\":{\"produccion\":11.71,\"rendimiento\":4.54},\"verano\":{\"produccion\":14.18,\"rendimiento\":5.5}}'),
(20, 13, 17, 'Simulación 07/07/2026 10:13', 'xgboost', 11.60, 73.00, 1058.40, 75.00, 5.50, 'arcilloso', 10.26, 4.3409, 44.54, 64.00, '{\"area\":0,\"fertilizante\":-0.4371,\"humedad\":-0.028,\"phSuelo\":0.1623,\"precipitacion\":0.0156,\"temperatura\":0.0998,\"tipoSuelo\":0.0114}', '[\"\\u2705 Temperatura \\u00f3ptima (24.5\\u00b0C) alineada con los requerimientos (21-27\\u00b0C).\",\"\\u2705 Humedad relativa adecuada (68.0%) para el cultivo.\",\"\\u2705 Precipitaci\\u00f3n adecuada (780 mm) en rango \\u00f3ptimo (600-800 mm).\",\"\\u26a0\\ufe0f Fertilizaci\\u00f3n baja (75 kg N\\/ha). Dosis recomendada: 180-200 kg N\\/ha. Fraccionamiento sugerido: 3 aplicaciones: \\u2022 Siembra \\u2022 30 dds \\u2022 55\\u201360 dds.\",\"\\ud83d\\udd34 pH del suelo muy \\u00e1cido (5.5). Rango \\u00f3ptimo: 6.0-6.5. Aplicar cal agr\\u00edcola para corregir acidez.\"]', '2026-07-07 03:13:42', 'Baja', '{\"lluvioso\":{\"produccion\":45.75,\"rendimiento\":4.46},\"sequia\":{\"produccion\":39.07,\"rendimiento\":3.81},\"verano\":{\"produccion\":45.75,\"rendimiento\":4.46}}'),
